def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the three-row palette: each row repeats the same nonzero sequence.
    palette = None
    for r in range(h - 2):
        seqs = [
            [(c, grid[rr][c]) for c in range(w) if grid[rr][c] != 0]
            for rr in range(r, r + 3)
        ]
        if seqs[0] and seqs[0] == seqs[1] == seqs[2]:
            palette = [v for c, v in seqs[0]]
            palette_cells = {
                (rr, c) for rr in range(r, r + 3)
                for c, v in seqs[0]
            }
            break

    if palette is None:
        return [row[:] for row in grid]

    # The shape matching the palette's middle color is the template.
    middle = len(palette) // 2
    template_color = palette[middle]
    cells = [
        (r, c) for r in range(h) for c in range(w)
        if grid[r][c] == template_color and (r, c) not in palette_cells
    ]
    if not cells:
        return [[0] * w for _ in range(h)]

    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    shape = [(r - r0, c - c0) for r, c in cells]
    step = r1 - r0 + 1

    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(palette):
        top = r0 + (i - middle) * step
        for dr, dc in shape:
            rr, cc = top + dr, c0 + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color

    return out
